scripts.script:
-- INFINITE CASH
spawn(function()
    while true do
        wait(0.01)
        local args = {
            [1] = {
                ["Model"] = game:GetService("ReplicatedStorage").Client.Assets.GymAssets.Customers.Olivia.Model,
                ["ItemName"] = "Liam"
            }
        }
        game:GetService("ReplicatedStorage").Client.Packages._Index:FindFirstChild("sleitnick_knit@1.6.0").knit.Services.NpcService.RE.CustomerPayment:FireServer(unpack(args))
    end
end)

-- INFINITE POWER 1
spawn(function()
    while true do
        wait(0.1)
        game:GetService("ReplicatedStorage").Client.Packages._Index["sleitnick_knit@1.6.0"].knit.Services.CharacterService.RF.GrowMuscle:InvokeServer({
            {["Name"] = "Chest", ["Chance"] = 60},
            {["Name"] = "Shoulders", ["Chance"] = 20},
            {["Name"] = "Triceps", ["Chance"] = 20}
        }, 99999999999999999)
    end
end)

-- INFINITE POWER 2
spawn(function()
